def fill_stock_after(apps, schema_editor):
    """Give existing movements their running stock figure, so history shows before and after."""
    StockMovement = apps.get_model("catalog", "StockMovement")
    running, batch = {}, []
    for m in StockMovement.objects.order_by("created_at", "id").only("id", "product_id", "quantity"):
        running[m.product_id] = running.get(m.product_id, 0) + m.quantity
        m.stock_after = running[m.product_id]
        batch.append(m)
    StockMovement.objects.bulk_update(batch, ["stock_after"], batch_size=500)


